package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class MagicMirrorsAudit {
 static int ticks;static volatile boolean prepared,menuReady,finished;static final BlockPos POS=InfusionAudit.POS;static MagicMirrors.MirrorEntity source,remote,localEss,remoteEss;static final List<BlockPos> jars=new ArrayList<>();static final List<BlockPos> peds=new ArrayList<>(TravellerBootsAudit.PEDESTALS.subList(0,4));
 static void check(boolean b,String message){if(!b)throw new IllegalStateException("TC4_MIRROR FAIL "+message);System.out.println("TC4_MIRROR PASS "+message);}
 static MagicMirrors.MirrorEntity put(ServerLevel l,BlockPos p,boolean essence,Direction face){l.setBlock(p.relative(face.getOpposite()),Blocks.STONE.defaultBlockState(),3);l.setBlock(p,(essence?MagicMirrors.ESSENTIA:MagicMirrors.ITEM).get().defaultBlockState().setValue(BlockStateProperties.FACING,face),3);return (MagicMirrors.MirrorEntity)l.getBlockEntity(p);}
 static void pair(MagicMirrors.MirrorEntity a,MagicMirrors.MirrorEntity b){a.link=b.getBlockPos();a.linkDimension=b.getLevel().dimension();a.restore();check(a.valid()&&b.valid(),"reciprocal same-type pair "+a.essentia());}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;var l=p.serverLevel();l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(25)).forEach(Entity::discard);var wand=p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow().copy();p.getInventory().clearContent();p.getInventory().setItem(8,wand);
  for(var key:List.of("Mirror","MirrorHand","MirrorEssentia")){var r=InfusionItemRecipes.all().stream().filter(x->x.key().equals(key)).findFirst().orElseThrow();check(InfusionItemRecipes.match(r.componentStacks(),new ItemStack(r.central().get()),Set.of(r.research()))==r&&InfusionItemRecipes.match(r.componentStacks(),new ItemStack(r.central().get()),Set.of())==null,"exact recipe and research "+key);}
  source=put(l,POS.offset(6,-2,-6),false,Direction.UP);p.getInventory().selected=0;p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(MagicMirrors.ITEM.get()));var hit=new BlockHitResult(source.getBlockPos().getCenter(),Direction.UP,source.getBlockPos(),false);var c=new UseOnContext(p,InteractionHand.MAIN_HAND,hit);check(p.getMainHandItem().getItem().onItemUseFirst(p.getMainHandItem(),c).consumesAction(),"actual mirror use binds unpaired source");var bound=p.getInventory().items.stream().filter(s->s.is(MagicMirrors.ITEM.get().asItem())&&NoteData.tag(s).contains("linkX")).findFirst().orElseThrow().copy();var next=POS.offset(9,-2,-6);l.setBlock(next.below(),Blocks.STONE.defaultBlockState(),3);p.setItemInHand(InteractionHand.MAIN_HAND,bound);check(((BlockItem)bound.getItem()).place(new BlockPlaceContext(p,InteractionHand.MAIN_HAND,bound,new BlockHitResult(next.below().getCenter().add(0,.5,0),Direction.UP,next.below(),false))).consumesAction(),"actual bound block placement");remote=(MagicMirrors.MirrorEntity)l.getBlockEntity(next);check(source.valid()&&remote.valid(),"placement restores reciprocal pair");check(source.getBlockState().getCollisionShape(l,source.getBlockPos()).isEmpty()&&source.getBlockState().getShape(l,source.getBlockPos()).bounds().getYsize()==.0625,"noncolliding flat1/16 selection");
  var item=new ItemEntity(l,source.getBlockPos().getX()+.5,source.getBlockPos().getY()+.01,source.getBlockPos().getZ()+.5,new ItemStack(Items.DIAMOND,4));item.setPickUpDelay(0);l.addFreshEntity(item);source.getBlockState().entityInside(l,source.getBlockPos(),item);check(item.isRemoved()&&remote.output.size()==1&&remote.output.get(0).getCount()==4&&source.instability==4,"actual collision queues full stack with source instability");var nbt=remote.saveWithFullMetadata(p.registryAccess());var loaded=new MagicMirrors.MirrorEntity(next,remote.getBlockState());loaded.loadWithComponents(nbt,p.registryAccess());check(loaded.output.size()==1&&loaded.output.get(0).getCount()==4&&loaded.linked,"queue and link persist fullNBT");
  // All six orientations retain native face attachment and a flat selection box.
  for(var d:Direction.values()){var t=put(l,POS.offset(5+d.get3DDataValue(),-1,4),false,d);check(t.getBlockState().canSurvive(l,t.getBlockPos())&&t.getBlockState().getCollisionShape(l,t.getBlockPos()).isEmpty(),"attached face "+d);}
  var nether=p.server.getLevel(Level.NETHER);var other=put(nether,new BlockPos(64,90,64),false,Direction.UP);var inter=put(l,POS.offset(-8,-2,-7),false,Direction.UP);pair(inter,other);var crossing=new ItemEntity(l,0,0,0,new ItemStack(Items.EMERALD,2));check(inter.transport(crossing)&&other.output.get(0).getCount()==2,"cross-dimension full stack delivery queue");other.keepTicking();
  localEss=put(l,POS.offset(-4,-2,-5),true,Direction.UP);remoteEss=put(l,POS.offset(40,-2,0),true,Direction.UP);pair(localEss,remoteEss);check(!localEss.take(Aspect.TRAVEL,2),"essentia request greater than one rejected");
  for(int x=-10;x<=10;x++)for(int y=-2;y<=0;y++)for(int z=-10;z<=10;z++){var at=POS.offset(x,y,z);if(l.getBlockEntity(at) instanceof WardedJarEntity)l.setBlock(at,Blocks.AIR.defaultBlockState(),3);}
  var r=InfusionItemRecipes.all().stream().filter(x->x.key().equals("Mirror")).findFirst().orElseThrow();int i=0;for(var a:r.aspects().getAspects()){var at=remoteEss.getBlockPos().offset(i++*2-2,1,2);l.setBlock(at,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(at);jar.state.aspect=a;jar.state.amount=8;jar.changed();jars.add(at);}check(localEss.take(Aspect.TRAVEL,1),"local mirror pulls one from directional remote jar");for(var at:jars){var jar=(WardedJarEntity)l.getBlockEntity(at);jar.state.amount=8;jar.changed();}
  ((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(new ItemStack(r.central().get()));for(i=0;i<4;i++){l.setBlock(peds.get(i),InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(peds.get(i))).setItem(r.componentStacks().get(i));}for(var at:InfusionAudit.components)if(!peds.contains(at)&&l.getBlockEntity(at) instanceof InfusionContent.PedestalEntity ped)ped.setItem(ItemStack.EMPTY);
  p.setItemInHand(InteractionHand.MAIN_HAND,wand);InfusionAudit.click(p,wand);check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==24,"actual altar starts mirror infusion powered through remote mirror");p.connection.teleport(POS.getX()+8,POS.getY()+2,POS.getZ()-12,0,28);prepared=true;
 }
 static void menu(ServerPlayer p){var nether=p.server.getLevel(Level.NETHER);var across=(MagicMirrors.MirrorEntity)nether.getBlockEntity(new BlockPos(64,90,64));check(across.output.isEmpty(),"destination in unoccupied Nether ticks and ejects queued items");check(remote.output.isEmpty(),"natural ticks eject queue one item per tick");var diamonds=p.serverLevel().getEntitiesOfClass(ItemEntity.class,new AABB(remote.getBlockPos()).inflate(8)).stream().filter(i->i.getItem().is(Items.DIAMOND)).mapToInt(i->i.getItem().getCount()).sum();check(diamonds==4,"exact four diamond output no duplicates");remote.add(new ItemStack(Items.COPPER_INGOT,2));remote.instability=200;remote.count=31;MagicMirrors.MirrorEntity.tick(p.level(),remote.getBlockPos(),remote.getBlockState(),remote);check(remote.output.get(0).getCount()==2,"instability200 slows ejection to squared16ticks");MagicMirrors.MirrorEntity.tick(p.level(),remote.getBlockPos(),remote.getBlockState(),remote);check(remote.output.get(0).getCount()==1,"instability200 ejects one at divisible16tick");remote.output.clear();remote.instability=0;source.setItem(0,new ItemStack(Items.COAL,3));check(remote.output.size()==1&&remote.output.get(0).getCount()==3&&source.getItem(0).isEmpty(),"hopper-style insertion forwards stack without exposing output inventory");remote.output.clear();var hand=new ItemStack(HandMirror.item());p.getInventory().selected=0;p.setItemInHand(InteractionHand.MAIN_HAND,hand);var c=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(source.getBlockPos().getCenter(),Direction.UP,source.getBlockPos(),false));hand.getItem().onItemUseFirst(hand,c);check(NoteData.tag(hand).contains("linkX")&&hand.isEnchanted()==false&&hand.hasFoil(),"actual hand binding to already linked source, original glint");hand.use(p.level(),p,InteractionHand.MAIN_HAND);check(p.containerMenu instanceof HandMirror.Menu,"actual hand use opens menu");p.getInventory().setItem(1,new ItemStack(Items.GOLD_INGOT,16));var m=(HandMirror.Menu)p.containerMenu;check(!m.quickMoveStack(p,29).isEmpty()&&m.contents.isEmpty()&&p.getInventory().getItem(1).isEmpty(),"actual shiftclick transports full16 stack immediately");check(p.serverLevel().getEntitiesOfClass(ItemEntity.class,new AABB(source.getBlockPos()).inflate(2)).stream().filter(i->i.getItem().is(Items.GOLD_INGOT)).mapToInt(i->i.getItem().getCount()).sum()==16,"full stack arrives at selected source, not linked partner");menuReady=true;}
 static void finish(ServerPlayer p){var l=p.serverLevel();p.closeContainer();check(!InfusionAudit.matrix.logic.crafting&&((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item().is(MagicMirrors.ITEM.get().asItem()),"natural altar creates mirror using remote essentia");for(var at:jars)check(((WardedJarEntity)l.getBlockEntity(at)).state.amount==0,"exact8remoteessentia consumed "+at);for(var at:peds)check(((InfusionContent.PedestalEntity)l.getBlockEntity(at)).item().isEmpty(),"component consumed "+at);var state=source.getBlockState();var drops=Block.getDrops(state,l,source.getBlockPos(),source);check(drops.size()==1&&NoteData.tag(drops.get(0)).contains("linkX"),"broken linked mirror preserves destination");l.setBlock(source.getBlockPos(),Blocks.AIR.defaultBlockState(),3);check(!remote.linked,"breaking mirror invalidates counterpart");var hand=p.getMainHandItem();check(HandMirror.target(hand,p)==null&&!hand.has(net.minecraft.core.component.DataComponents.CUSTOM_DATA),"broken hand destination clears binding");finished=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.mirrorAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==160){check(prepared&&MagicMirrorsClient.rendered>0,"server fixtures and native renderer complete");LiquidDeathAudit.shot(mc,"mirrors-linked-world.png");}if(ticks==200)server.execute(()->menu(server.getPlayerList().getPlayer(id)));if(ticks==220){check(menuReady&&mc.screen instanceof MagicMirrorsClient.Screen,"actual hand mirror client screen");LiquidDeathAudit.shot(mc,"mirrors-hand-menu.png");}if(ticks==900)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks>=920&&(ticks-920)%15==0){check(finished,"all server transfer and infusion assertions complete");int i=(ticks-920)/15;if(i>=5){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(i<2?"MIRROR":i==2?"MIRRORHAND":"MIRRORESSENTIA"),i==1||i==4?2:0);mc.setScreen(book);}if(ticks>=925&&(ticks-925)%15==0)LiquidDeathAudit.shot(mc,"mirrors-book-"+(ticks-925)/15+".png");}
}
